import type { Address, PublicClient } from 'viem'

import type { TokensSchema } from '@/types/tokens'

import { getTokenDecimals } from './get-token-decimals'

export const validateDecimals = async ({
  errors,
  publicClient,
  token,
}: {
  errors: Array<string>
  publicClient: PublicClient
  token: TokensSchema['tokens'][number]
}) => {
  const decimals = await getTokenDecimals({
    errors,
    publicClient,
    tokenAddress: token.address as Address,
  })

  if (token.decimals !== decimals) {
    errors.push(
      `${token.symbol}’s decimals does not match the on-chain decimals ${decimals}`,
    )
  }
}

import { type Address, erc20Abi, type PublicClient } from 'viem'

import { BERA_TOKEN_ADDRESS } from './constants'

const BERA_DECIMALS = 18

export const getTokenDecimals = async ({
  errors,
  publicClient,
  tokenAddress,
}: {
  errors: Array<string>
  publicClient: PublicClient
  tokenAddress: Address
}) => {
  if (tokenAddress === BERA_TOKEN_ADDRESS) {
    return BERA_DECIMALS // hack for BERA
  }

  const symbol = await publicClient.readContract({
    abi: erc20Abi,
    address: tokenAddress,
    functionName: 'decimals',
  })
  if (!symbol) {
    errors.push(`${tokenAddress} does not have decimals on the contract`)
  }
  return symbol
}

