import { readdirSync } from 'node:fs'
import { createPublicClient, http } from 'viem'

import { supportedChains } from '@/config/chains'
import type { TokensSchema } from '@/types/tokens'
import type { VaultsSchema } from '@/types/vaults'

import { getFile } from './_/get-file'
import { getJsonFile } from './_/get-json-file'
import { isValidChain } from './_/is-valid-chain'
import { outputScriptStatus } from './_/output-script-status'
import { validateList } from './_/validate-list'
import { validateVaultDetails } from './_/validate-vault-details'

const schema = getFile('schema/vaults-schema.json')
const folderPath = 'src/vaults'

const validateVaultsByChain = async ({
  chain,
}: {
  chain: keyof typeof supportedChains
}) => {
  const errors: Array<string> = []
  const path = `${folderPath}/${chain}.json`
  const vaults: VaultsSchema = getJsonFile({
    chain,
    path,
  })
  const tokens: TokensSchema = getJsonFile({
    chain,
    path: `src/tokens/${chain}.json`,
  })
  const publicClient = createPublicClient({
    chain: supportedChains[chain],
    transport: http(),
  })
  const slugs: Array<string> = []
  const beraRewardsVaults = new Set<string>()

  validateList({ errors, list: vaults, schema, type: 'vaults' })
  const promisedVaultDetails = vaults.vaults.map(
    async (vault) =>
      await validateVaultDetails({
        beraRewardsVaults,
        errors,
        publicClient,
        slugs,
        tokens,
        vault,
      }),
  )
  await Promise.all(promisedVaultDetails)
  outputScriptStatus({ chain, errors, type: 'Vaults' })
}

const validateVaults = async () => {
  const promises = readdirSync(folderPath).map(async (file) => {
    const chain = file.replace('.json', '')

    if (!isValidChain(chain)) {
      throw new Error(`Unsupported chain: ${chain}`)
    }
    await validateVaultsByChain({ chain })
  })

  await Promise.all(promises)
}

await validateVaults()

import {
  readFileSync,
  writeFileSync,
  mkdirSync,
  readdirSync,
  rmSync,
  existsSync,
} from 'fs'
import { resolve } from 'path'

const INDENTATION_SPACES = 2

const assetTypes = ['tokens', 'vaults', 'validators']
const distDirName = 'dist'

// Process asset types
for (const assetType of assetTypes) {
  const srcDir = resolve(process.cwd(), `./src/${assetType}`)
  const distDir = resolve(process.cwd(), `./${distDirName}/${assetType}`)

  // Skip if source directory doesn't exist
  if (!existsSync(srcDir)) {
    console.log(`Skipping ${assetType} - source directory does not exist`)
    continue
  }

  // Remove existing dist directory if it exists
  if (existsSync(distDir)) {
    rmSync(distDir, { force: true, recursive: true })
  }

  // Create the dist directory
  mkdirSync(distDir, { recursive: true })

  // Get all JSON files in the source directory
  const jsonFiles = readdirSync(srcDir).filter((file) => file.endsWith('.json'))

  for (const jsonFile of jsonFiles) {
    const jsonPath = resolve(srcDir, jsonFile)
    const tsPath = resolve(distDir, jsonFile.replace('.json', '.ts'))

    const jsonContent = readFileSync(jsonPath, 'utf-8')
    const data = JSON.parse(jsonContent)

    const tsContent = `export const ${assetType} = ${JSON.stringify(data[assetType], null, INDENTATION_SPACES)}\n`

    writeFileSync(tsPath, tsContent)
    console.log(`Converted ${assetType}/${jsonFile} to TypeScript`)
  }
}

// Process Protocols
const srcPath = resolve(process.cwd(), `./src/protocols.json`)
const distPath = resolve(process.cwd(), `./${distDirName}/protocols.ts`)

const jsonContent = readFileSync(srcPath, 'utf-8')
const data = JSON.parse(jsonContent)

const tsContent = `export const protocols = ${JSON.stringify(data.protocols, null, INDENTATION_SPACES)}\n`

writeFileSync(distPath, tsContent)
console.log(`Converted protocols.json to TypeScript`)

